    table(['Original column', 'Original value'], sourceFields(context).map(([field, value]) => [
      '<span class="mono">' + esc(field) + '</span>', block(value, '(blank)')
    ])) + '</section>' +
    (Object.keys(otherDecision).length || Object.keys(extraEnvelope).length ?
